input.content:
/* Focused single-file check for the ported CVE-2017-16995 change unit.
 *
 * It reproduces the exact storage type (union s64 imm), the ported
 * check_alu_op MOV-K conditional extension, the __printf-style debug
 * print, and the kernel runtime semantics of ALU_MOV_K / ALU64_MOV_K /
 * JMP_JEQ_K. It is NOT a kernel build.
 */
#include <stdio.h>
#include <stdint.h>
#include <assert.h>
#include <string.h>
#include <stdarg.h>

typedef int64_t  s64;
typedef uint64_t u64;
typedef int32_t  s32;

struct bpf_insn {
	uint8_t code;
	int8_t  dst;
	int8_t  src;
	int16_t off;
	s32     imm;
};

#define BPF_CLASS(code) ((code) & 0x07)
#define BPF_ALU64 0x07
#define BPF_ALU   0x04
#define BPF_MOV   0xb0
#define BPF_K     0x00

#define CONST_IMM 8

struct reg_state {
	int type;
	union {
		s64 imm;
		struct { void *map_ptr; };
	};
};

/* Same declaration as kernel/bpf/verifier.c */
static __attribute__((format(printf, 1, 2))) int verbose(const char *fmt, ...)
{
	char buf[128];
	va_list args;
	va_start(args, fmt);
	int n = vsnprintf(buf, sizeof(buf), fmt, args);
	va_end(args);
	return n;
}

/* Ported check_alu_op MOV|K tail */
static void verifier_mov_k(struct reg_state *regs, struct bpf_insn *insn)
{
	u64 imm;

	if (BPF_CLASS(insn->code) == BPF_ALU64)
		imm = insn->imm;
	else
		imm = (u32)insn->imm;

	regs[insn->dst].type = CONST_IMM;
	regs[insn->dst].imm = imm;
}

/* Old (vulnerable) target behavior: int imm, unconditional s32 store */
struct old_reg_state { int type; union { int imm; void *map_ptr; }; };
static void verifier_mov_k_old(struct old_reg_state *regs, struct bpf_insn *insn)
{
	regs[insn->dst].type = CONST_IMM;
	regs[insn->dst].imm = insn->imm;
}

/* Runtime: ALU_MOV_K / ALU64_MOV_K / consume */
static u64 rt_alu_mov_k(u64 dst, s32 imm)   { (void)dst; return (u32)imm; }
static u64 rt_alu64_mov_k(u64 dst, s32 imm) { (void)dst; return (u64)(s64)imm; }
static int rt_jeq_k(u64 dst, s32 imm)       { return dst == (u64)(s64)imm; }

int main(void)
{
	struct reg_state regs[1];
	struct bpf_insn insn;

	/* positive path: 64-bit MOV immediate sign-extends (no behavior change) */
	memset(&insn, 0, sizeof(insn));
	insn.code = BPF_ALU64 | BPF_MOV | BPF_K; insn.imm = -1;
	verifier_mov_k(regs, &insn);
	assert(regs[0].imm == (s64)-1);
	assert((u64)regs[0].imm == rt_alu64_mov_k(0, -1));
	verbose("ALU64 mov -1 -> %lld\n", regs[0].imm);

	/* negative path: 32-bit MOV 0xffffffff must be zero-extended */
	memset(&insn, 0, sizeof(insn));
	insn.code = BPF_ALU | BPF_MOV | BPF_K; insn.imm = -1; /* 0xffffffff */
	verifier_mov_k(regs, &insn);
	assert(regs[0].imm == (s64)0xffffffffULL);
	assert((u64)regs[0].imm == rt_alu_mov_k(0, -1));
	verbose("ALU   mov 0xffffffff -> %lld (runtime %llu)\n",
		regs[0].imm, (unsigned long long)rt_alu_mov_k(0, -1));

	/* branch pruning: JEQ r, -1 differs from runtime for the 32-bit move */
	assert(((u64)regs[0].imm == (u64)(s64)-1) == 0);   /* verifier: not equal */
	assert(rt_jeq_k(regs[0].imm, -1) == 0);            /* runtime: not equal */

	/* old model: int imm = -1 wrongly equals the -1 immediate */
	struct old_reg_state oregs[1];
	memset(&insn, 0, sizeof(insn));
	insn.code = BPF_ALU | BPF_MOV | BPF_K; insn.imm = -1;
	verifier_mov_k_old(oregs, &insn);
	assert(oregs[0].imm == -1);
	assert(((s64)oregs[0].imm == (s64)-1) == 1);       /* verifier: equal (WRONG) */
	assert(rt_jeq_k((u64)0xffffffffULL, -1) == 0);     /* runtime: not equal */
	verbose("old int model would prune on JEQ/-1; runtime would not\n");

	printf("single-file semantics check: PASS\n");
	return 0;
}

